def e(value):
    return escape(str(value), quote=True)


def _root(page):
    return '../../'


def _nav(root, current):
    groups=[]
    for heading, links in NAV:
        items=[]
        for route,label in links:
            active=' aria-current="page"' if route==current else ''
            items.append(f'<a class="mega-menu__item" href="{e(root+route)}"{active}><strong>{e(label)}</strong><span>Guide daté, règles et limites de vérification.</span></a>')
        groups.append(f'<div class="home-mega__group"><p class="eyebrow">{e(heading)}</p>{"".join(items)}</div>')
    return (f'<nav class="site-nav" id="global-nav" aria-label="Navigation principale" data-site-nav>'
            f'<a class="site-nav__link" href="{root}">Accueil</a><a class="site-nav__link" href="{root}pages/maps/">Cartes</a>'
            f'<details class="mega-menu home-mega" data-nav-disclosure><summary class="mega-menu__summary">Explorer le guide</summary>'
            f'<div class="mega-menu__panel home-mega__panel phase9-mega">{"".join(groups)}</div></details>'
            f'<a class="site-nav__link" href="{root}#actualites">Actualités</a><a class="site-nav__link" href="{root}pages/events/">Événements</a></nav>')


def _quick(page):
    return ''.join(
        f'<a class="guide-quick__link" href="#{e(anchor)}"><span class="guide-quick__no" aria-hidden="true">{i:02d}</span>'
        f'<span class="guide-quick__copy"><strong>{e(title)}</strong><small>{e(label)}</small></span>'
        f'<span class="guide-quick__arrow" aria-hidden="true">↘</span></a>'
        for i,(anchor,title,label) in enumerate(page['quick'],1))


def _source_html(keys, sources):
    rows=[]
    for key in keys:
        item=sources.get(key)
        if not item: raise ValueError(f'Source PHASE_9 absente de docs/sources.json : {key}')
        title=item.get('titre') or key
        url=item.get('url') or ''
        kind=(item.get('type') or 'source').replace('_',' ')
        note=item.get('usage_phase_9') or item.get('usage') or 'Contexte documentaire; vérifier la version actuelle dans le jeu ou la documentation.'
        date_label=item.get('date_releve_phase_9') or 'Consultation directe non consignée; voir la source pour son statut actuel.'
        rows.append(f'<li><span class="phase9-source__type">{e(kind)}</span><div><a href="{e(url)}" rel="noopener noreferrer">{e(title)} <span aria-hidden="true">↗</span></a><p>{e(note)}</p><small>{e(date_label)}</small></div></li>')
    return ''.join(rows)


def _cards(ids, root):
    by_id={p['id']:p for p in PAGES}
    return '<div class="phase9-card-grid">'+''.join(
        f'<a class="phase9-link-card" href="{e(root+by_id[i]["route"])}"><strong>{e(by_id[i]["title"])}</strong><span>{e(by_id[i]["lead"])}</span><span aria-hidden="true" class="phase9-link-card__arrow">↗</span></a>'
        for i in ids)+'</div>'


def _fig(src, alt, caption, root):
    return f'<figure class="phase9-figure"><img src="{e(root+src)}" width="1376" height="768" alt="{e(alt)}" loading="lazy" decoding="async"><figcaption>{e(caption)}</figcaption></figure>'


def _section(anchor, n, eyebrow, title, intro, content):
    return f'<section class="guide-section phase9-section" id="{e(anchor)}" tabindex="-1"><div class="phase9-section__heading"><p class="guide-kicker"><span>{e(n)}</span> {e(eyebrow)}</p><h2>{e(title)}</h2><p>{intro}</p></div>{content}</section>'


