def build_phase9(base, patch, read, compact):
    source_doc=json.loads(read('docs/sources.json'))
    sources=source_doc['sources']
    review=date.fromisoformat(REVIEW)
    output={}
    search=[]
    keywords={
      'spt':['SPT','SP-Tushonka','Single Player Tarkov','PvE officiel','Bleeding Edge','Fika'],
      'installation':['installer','SPT 4.1.6','build EFT','.NET','SP-Tushonka'],
      'mods':['mods','The Forge','SAIN','SVM','dépendances','compatibilité','4.1.6'],
      'fika':['Project Fika','coop','SPT','serveur','plugin','version Fika'],
      'troubleshooting':['dépannage','runtime','logs','Linux','Proton','mods','SPT'],
      'arena':['Arena','BlastGang','TeamFight','CheckPoint','Last Hero','BattlePass','patch 0.6.2.5'],
      'events':['événement','Halloween','Blackout','Drops','Kord Breach','Wild Wild Woods','Full Speed Ahead','Duck Hunt','BloodLust']}
    for page in PAGES:
        for key in page['sources']:
            if key not in sources: raise ValueError(f'Source {key} absente pour {page["id"]}')
        output[page['file']]=_render_page(page,sources,base,patch)
        search.append({'title':page['title'],'href':page['route'],'tag':'PHASE_9 · '+page['label'],'summary':page['lead'],'keywords':keywords[page['id']]})
    return output,search,review


def validate_phase9():
    expected={
      'pages/spt-tushonka/index.html','pages/spt-tushonka/installation.html','pages/spt-tushonka/mods.html',
      'pages/spt-tushonka/fika.html','pages/spt-tushonka/troubleshooting.html','pages/arena/index.html','pages/events/index.html'}
    if len(PAGES)!=7 or {p['file'] for p in PAGES}!=expected: raise SystemExit('Les sept routes PHASE_9 ne correspondent pas au plan.')
    for page in PAGES:
        image=ROOT/page['hero']
        if not image.is_file() or image.suffix.lower()!='.jpg' or not image.read_bytes().startswith(b'\xff\xd8'):
            raise SystemExit('Illustration JPG absente ou invalide : '+page['hero'])
    source_doc=json.loads((ROOT/'docs/sources.json').read_text(encoding='utf-8'))
    missing=sorted({key for page in PAGES for key in page['sources'] if key not in source_doc['sources']})
    if missing: raise SystemExit('Sources PHASE_9 absentes : '+', '.join(missing))
    print(f'PHASE_9 source OK · {len(PAGES)} routes · 7 JPG · sources vérifiées le {REVIEW_DATE}')

if __name__=='__main__':
    validate_phase9()
